def build_agent(sandbox):
    # Beam parameters
    beam_width = 0.5
    beam_height = 0.1
    beam_density = 5.0  # 3 * 0.5 * 0.1 * 5.0 = 0.75 kg total
    y_positions = [2.40, 2.00, 1.75]  # Top, middle, bottom barriers
    x_positions = [5.45, 5.90, 6.35]  # Evenly spaced within build x-zone

    beams = []
    for x, y in zip(x_positions, y_positions):
        beam = sandbox.add_static_beam(x, y, beam_width, beam_height, density=beam_density)
        sandbox.set_material_properties(beam, restitution=0.0)
        beams.append(beam)

    return beams[0]  # Return any representative beam


def agent_action(sandbox, agent_body, step_count):
    NUDGE_PERIOD = 32
    NUDGE_FORCE_SMALL = 30.0
    NUDGE_FORCE_MEDIUM = 25.5

    if step_count % NUDGE_PERIOD != 0:
        return

    # Nudge small particles in the wrong zone downward
    for p in sandbox.get_particles_small():
        if p.active:
            y = p.position.y
            if y > 2.52:
                sandbox.apply_force(p, (0, -NUDGE_FORCE_SMALL))  # Above large zone
            elif y > 1.92:
                sandbox.apply_force(p, (0, -NUDGE_FORCE_SMALL))  # In sieve band

    # Nudge medium particles in the wrong zone downward
    for p in sandbox.get_particles_medium():
        if p.active and p.position.y > 2.52:
            sandbox.apply_force(p, (0, -NUDGE_FORCE_MEDIUM))  # Above large zone
